<?php
require_once __DIR__ . '/../../src/Services/ApiService.php';
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');
function respond($value,int $status=200): void {http_response_code($status);echo json_encode($value,JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function body(): array {$v=json_decode(file_get_contents('php://input'),true);if(!is_array($v))throw new InvalidArgumentException('Request body must be a JSON object');return $v;}
function bridge_auth(): void {$expected=(string)(config()['bridge_token']??'');$given=(string)($_SERVER['HTTP_X_BRIDGE_TOKEN']??'');if($expected===''||!hash_equals($expected,$given))respond(['error'=>'unauthorized bridge'],401);}
try {
 $pdo=db();$method=$_SERVER['REQUEST_METHOD'];$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)??'/';$path=preg_replace('#^/api#','',$path);$path=rtrim($path,'/')?:'/';
 if($method==='GET'&&$path==='/status'){
  $counts=$pdo->query("SELECT component,state,last_seen_at,updated_at FROM system_status")->fetchAll();$latest=$pdo->query('SELECT MAX(received_at) FROM uplink_packets')->fetchColumn();respond(['database'=>'ONLINE','components'=>$counts,'last_packet_at'=>$latest,'demo_mode'=>'data is marked per record']);
 }
 if($method==='GET'&&$path==='/hikers'){
  $q=$pdo->query("SELECT h.*,p.id packet_id,p.latitude,p.longitude,p.gps_accuracy_m,p.satellite_count,p.battery_level,p.classification,p.received_at,p.test_mode,(SELECT r.received_by_node FROM packet_receptions r WHERE r.uplink_packet_id=p.id ORDER BY r.id DESC LIMIT 1) last_heard_by FROM hiker_nodes h LEFT JOIN uplink_packets p ON p.id=(SELECT MAX(p2.id) FROM uplink_packets p2 WHERE p2.hiker_node_id=h.id) ORDER BY h.id");respond(['hikers'=>$q->fetchAll()]);
 }
 if($method==='GET'&&preg_match('#^/hikers/([A-Za-z0-9_-]+)/latest$#',$path,$m)){$q=$pdo->prepare('SELECT p.*,h.node_id,h.display_name FROM uplink_packets p JOIN hiker_nodes h ON h.id=p.hiker_node_id WHERE h.node_id=? ORDER BY p.id DESC LIMIT 1');$q->execute([$m[1]]);$v=$q->fetch();if(!$v)respond(['error'=>'hiker or position not found'],404);respond($v);}
 if($method==='GET'&&$path==='/positions/latest'){$q=$pdo->query('SELECT h.node_id,h.display_name,p.* FROM hiker_nodes h LEFT JOIN uplink_packets p ON p.id=(SELECT MAX(x.id) FROM uplink_packets x WHERE x.hiker_node_id=h.id) ORDER BY h.id');respond(['positions'=>$q->fetchAll()]);}
 if($method==='GET'&&$path==='/safe-zone')respond(['safe_zone'=>active_zone($pdo)]);
 if($method==='PUT'&&$path==='/safe-zone'){ $v=save_zone($pdo,body());respond(['safe_zone'=>$v],201); }
 if($method==='GET'&&($path==='/events'||$path==='/logs/packets')){
  $limit=max(1,min(200,(int)($_GET['limit']??50)));$offset=max(0,(int)($_GET['offset']??0));$conditions=[];$params=[];
  if(isset($_GET['node_id'])){$conditions[]='h.node_id=?';$params[]=(string)$_GET['node_id'];}if(isset($_GET['test_mode'])){$conditions[]='p.test_mode=?';$params[]=(int)(bool)$_GET['test_mode'];}if(isset($_GET['classification'])){$conditions[]='p.classification=?';$params[]=(string)$_GET['classification'];}
  if($path==='/events'){$sql='SELECT e.*,h.node_id FROM system_events e LEFT JOIN hiker_nodes h ON h.id=e.hiker_node_id';$conds=[];$ep=[];if(isset($_GET['node_id'])){$conds[]='h.node_id=?';$ep[]=(string)$_GET['node_id'];}if(isset($_GET['event_type'])){$conds[]='e.event_type=?';$ep[]=(string)$_GET['event_type'];}if(isset($_GET['test_mode'])){$conds[]='e.test_mode=?';$ep[]=(int)(bool)$_GET['test_mode'];}if($conds)$sql.=' WHERE '.implode(' AND ',$conds);$sql.=' ORDER BY e.id DESC LIMIT '.$limit.' OFFSET '.$offset;$q=$pdo->prepare($sql);$q->execute($ep);respond(['events'=>$q->fetchAll(),'limit'=>$limit,'offset'=>$offset]);}
  $sql='SELECT p.*,h.node_id,r.received_by_node,r.path_type,r.rssi_dbm,r.snr_db FROM uplink_packets p JOIN hiker_nodes h ON h.id=p.hiker_node_id LEFT JOIN packet_receptions r ON r.uplink_packet_id=p.id';if($conditions)$sql.=' WHERE '.implode(' AND ',$conditions);$sql.=' ORDER BY p.id DESC LIMIT '.$limit.' OFFSET '.$offset;$q=$pdo->prepare($sql);$q->execute($params);respond(['packets'=>$q->fetchAll(),'limit'=>$limit,'offset'=>$offset]);
 }
 if($method==='POST'&&$path==='/commands/storm-turn-back'){$v=body();$all=($v['all']??false)===true;$targets=[];if($all)$targets=$pdo->query('SELECT id,node_id FROM hiker_nodes WHERE is_enabled=1')->fetchAll();else{$node=trim((string)($v['node_id']??''));$q=$pdo->prepare('SELECT id,node_id FROM hiker_nodes WHERE node_id=? AND is_enabled=1');$q->execute([$node]);$h=$q->fetch();if(!$h)throw new InvalidArgumentException('enabled node_id or all:true is required');$targets=[$h];}if(!$targets)throw new InvalidArgumentException('no enabled hiker nodes');$pdo->beginTransaction();try{$q=$pdo->prepare("INSERT INTO downlink_commands(hiker_node_id,command_type,payload_json,test_mode) VALUES(?,'STORM_TURN_BACK',?,?)");$a=$pdo->prepare("INSERT INTO operator_actions(action_type,target_node_id,details_json,test_mode) VALUES('STORM_TURN_BACK',?,?,?)");$ids=[];foreach($targets as $t){$demo=!empty($v['test_mode']);$q->execute([$t['id'],json_value(['demo'=>$demo]),$demo?1:0]);$ids[]=['command_id'=>(int)$pdo->lastInsertId(),'node_id'=>$t['node_id'],'status'=>'QUEUED'];$a->execute([$t['id'],json_value(['command_id'=>end($ids)['command_id']]),$demo?1:0]);}$pdo->commit();respond(['commands'=>$ids,'test_mode'=>!empty($v['test_mode'])]);}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($method==='GET'&&$path==='/commands/pending'){bridge_auth();$q=$pdo->query("SELECT c.id,h.node_id,c.sequence_number,c.command_type,c.payload_json,c.status,c.created_at,c.test_mode FROM downlink_commands c JOIN hiker_nodes h ON h.id=c.hiker_node_id WHERE c.status='QUEUED' ORDER BY c.id LIMIT 100");respond(['commands'=>$q->fetchAll()]);}
 if($method==='POST'&&$path==='/bridge/ingest'){bridge_auth();$result=ingest_packet($pdo,body());respond($result,201);}
 if($method==='POST'&&$path==='/bridge/status'){bridge_auth();$v=body();$component=$v['component']??'';$state=$v['state']??'';if(!in_array($component,['BASE_CAMP','SERIAL_BRIDGE','CHECKPOINT'],true)||!in_array($state,['ONLINE','OFFLINE','UNKNOWN'],true))throw new InvalidArgumentException('valid component and state required');$q=$pdo->prepare('INSERT INTO system_status(component,state,last_seen_at,details_json) VALUES(?,?,NOW(),?) ON DUPLICATE KEY UPDATE state=VALUES(state),last_seen_at=VALUES(last_seen_at),details_json=VALUES(details_json)');$q->execute([$component,$state,json_value($v['details']??null)]);respond(['ok'=>true]);}
 if($method==='POST'&&preg_match('#^/commands/([0-9]+)/status$#',$path,$m)){bridge_auth();$v=body();$status=$v['status']??'';if(!in_array($status,['SENT_TO_BASE','DELIVERED','RECEIVED','FAILED','TIMED_OUT'],true))throw new InvalidArgumentException('invalid command status');$col=match($status){'SENT_TO_BASE'=>'sent_at','DELIVERED'=>'delivered_at','RECEIVED'=>'received_at',default=>null};$sql='UPDATE downlink_commands SET status=?,failure_reason=?'.($col?",$col=NOW()":'').' WHERE id=?';$q=$pdo->prepare($sql);$q->execute([$status,isset($v['failure_reason'])?substr((string)$v['failure_reason'],0,500):null,(int)$m[1]]);if(!$q->rowCount())respond(['error'=>'command not found or unchanged'],404);respond(['ok'=>true,'status'=>$status]);}
 if($method==='GET'&&$path==='/research/summary'){$q=$pdo->query("SELECT COUNT(*) packet_count,SUM(test_mode=1) demo_packet_count,SUM(classification='INSIDE') inside_count,SUM(classification='OUTSIDE') outside_count FROM uplink_packets");respond(['summary'=>$q->fetch(),'note'=>'Descriptive totals only; study performance summaries are a later milestone.']);}
 respond(['error'=>'not found'],404);
} catch(InvalidArgumentException $e){respond(['error'=>$e->getMessage()],400);}catch(Throwable $e){error_log($e->__toString());respond(['error'=>'backend error; check local server log'],500);}

